<?php $e=static fn(mixed $value):string=>(is_scalar($value)||$value===null)?authEscape($value):'';$section=$page['section'];$detail=$page['detail'];$titles=['returns'=>'Devoluciones de clientes','closing'=>'Cierre del vendedor','credit'=>'Control de crédito'];
