<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($titles[$section]) ?> | Vent-As</title><?php require dirname(__DIR__).'/partials/favicon.php'; ?>
<link rel="stylesheet" href="../../css/app.css?v=<?= filemtime(dirname(__DIR__,2).'/css/app.css') ?>"><link rel="stylesheet" href="../../css/modules.css?v=<?= filemtime(dirname(__DIR__,2).'/css/modules.css') ?>"><link rel="stylesheet" href="../../css/searchable-select.css"><script src="../../js/app.js?v=<?= filemtime(dirname(__DIR__,2).'/js/app.js') ?>" defer></script><script src="../../js/searchable-select.js" defer></script><?php require dirname(__DIR__).'/partials/theme.php'; ?><link rel="stylesheet" href="../../css/direct-sales.css?v=<?= filemtime(dirname(__DIR__,2).'/css/direct-sales.css') ?>"></head>
<body class="module-workspace direct-workspace" data-module="venta_directa"><div class="app-shell"><?php require dirname(__DIR__).'/partials/top-navigation.php'; ?>
<main class="direct-main"><header class="direct-heading"><div><a class="overview-link" href="../../index.php">← Módulos</a><h1><?= $e($titles[$section]) ?></h1></div></header>
<nav class="direct-tabs" aria-label="Ventas Directas"><?php foreach($nav as [$href,$label]): ?><a href="<?= $e($href) ?>" <?= basename($href)===basename($_SERVER['SCRIPT_NAME'])?'aria-current="page"':'' ?>><?= $e($label) ?></a><?php endforeach; ?></nav>
<?php foreach($page['errors'] as $error): ?><p class="notice notice-error" role="alert"><?= $e($error) ?></p><?php endforeach; ?>
<?php if($section==='credit'): ?>
<section class="contact-sheet direct-supply"><p>Por defecto se advierte y se permite vender. El saldo incluye facturas registradas de este cliente; los cobros en revisión no lo reducen hasta confirmarse. El control se aplica a nuevos plazos con vencimiento futuro en Ventas Directas.</p>
<form method="get" class="direct-supply-picker"><label>Cliente<select name="contact_id" required><option value="">Selecciona un cliente</option><?php foreach($page['customers'] as $customer): ?><option value="<?= (int)$customer['id'] ?>" <?= (int)($page['credit']['contact_id']??0)===(int)$customer['id']?'selected':'' ?>><?= $e($customer['name']) ?></option><?php endforeach; ?></select></label><button class="contact-button" type="submit">Consultar</button></form>
<?php if($page['credit']): $credit=$page['credit']; ?><p>Saldo actual: <strong><?= $e($page['exposure']['debt'].' '.$page['exposure']['currency']) ?></strong> · Vencido: <?= $e($page['exposure']['overdue'].' '.$page['exposure']['currency']) ?></p>
<form method="post" class="direct-simple-form"><input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><input type="hidden" name="action" value="save_credit"><input type="hidden" name="contact_id" value="<?= (int)$credit['contact_id'] ?>"><input type="hidden" name="version" value="<?= (int)$credit['version'] ?>">
<label>Límite de crédito (<?= $e($page['settings']['primary_code']) ?>)<input inputmode="decimal" name="credit_limit" value="<?= $e($page['input']['credit_limit']??$page['exposure']['limit']??'') ?>"><small>Vacío: sin límite. Cero: toda venta a crédito genera advertencia.</small></label>
<label>Si excede el límite o tiene deuda vencida<select name="policy"><option value="warn" <?= ($credit['policy']??'warn')==='warn'?'selected':'' ?>>Advertir y permitir</option><option value="block" <?= $credit['policy']==='block'?'selected':'' ?>>Bloquear nuevas ventas a crédito</option></select></label>
<?php if(permissionHas('venta_directa.configuration','configure')): ?><button class="contact-button contact-button-primary" type="submit">Guardar control de crédito</button><?php endif; ?></form><?php endif; ?></section>
<?php elseif($section==='returns'): ?>
<?php if($page['sale']): ?><section class="contact-sheet direct-supply"><h2><?= $e($detail?$detail['invoice_name']:'Devolución de la venta') ?></h2>
<?php if($detail): ?><p>Estado: <strong><?= $e(['pending'=>'Pendiente de revisión','done'=>'Recibida y acreditada','rejected'=>'Rechazada'][$detail['status']]) ?></strong> · <?= $e($detail['seller_name']) ?></p><p><?= $e($detail['payload']['reason']) ?></p>
<div class="direct-request-lines"><?php foreach($page['lines'] as $line): if(!isset($detail['payload']['lines'][$line['id']]))continue; ?><div><span><?= $e($line['product_name']) ?></span><strong><?= $e($detail['payload']['lines'][$line['id']]) ?></strong></div><?php endforeach; ?></div>
<?php if($detail['status']==='pending'&&permissionScope('venta_directa.returns','confirm')==='all'): ?><form method="post" class="direct-simple-form"><input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><label>Observación / motivo de rechazo<textarea name="decision_note" maxlength="1000"></textarea></label><p>Confirmar implica recibir físicamente los productos en la ubicación de la entrega original y registrar la nota de crédito. No devuelve dinero automáticamente. Los pagos en revisión deben resolverse antes.</p><div class="direct-actions"><button class="contact-button contact-button-primary" name="action" value="direct_return_approve">Recibir y crear nota de crédito</button><?php if(permissionScope('venta_directa.returns','cancel')==='all'): ?><button class="contact-button" name="action" value="direct_return_reject">Rechazar</button><?php endif; ?></div></form><?php endif; ?>
<?php if($detail['status']==='done'): ?><div class="direct-actions"><a class="contact-button" href="../inventario/operaciones.php?type=delivery&amp;id=<?= (int)$detail['operation_id'] ?>">Devolución de inventario</a><a class="contact-button" href="../contabilidad/index.php?type=customer&amp;id=<?= (int)$detail['credit_id'] ?>">Nota de crédito / reembolso</a></div><p>La nota ajusta el saldo y las comisiones de la factura. Si corresponde un reembolso, se gestiona y valida por separado.</p><?php endif; ?><p><?= $e($detail['decision_note']) ?></p>
<?php elseif(permissionHas('venta_directa.returns','create')): ?><form method="post" class="direct-simple-form"><input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><input type="hidden" name="action" value="direct_return"><input type="hidden" name="sale_id" value="<?= (int)$page['sale']['id'] ?>"><input type="hidden" name="request_key" value="<?= $e($page['input']['request_key']??$page['key']) ?>">
<p>Indica lo recibido del cliente. El supervisor revisará y confirmará la devolución; enviar esta solicitud no mueve inventario ni modifica la factura.</p>
<?php foreach($page['lines'] as $line): ?><label><?= $e($line['product_name']) ?> (facturado: <?= $e($line['quantity']) ?>)<input type="number" inputmode="decimal" min="0" max="<?= $e($line['quantity']) ?>" step="0.01" name="quantities[<?= (int)$line['id'] ?>]" value="<?= $e($page['input']['quantities'][$line['id']]??'0') ?>"></label><?php endforeach; ?>
<label>Motivo *<textarea name="reason" maxlength="255" required><?= $e($page['input']['reason']??'') ?></textarea></label><button class="contact-button contact-button-primary">Enviar devolución para revisión</button></form><?php endif; ?></section><?php endif; ?>
<section class="contact-sheet direct-supply"><h2>Devoluciones registradas</h2><?php foreach($page['rows'] as $row): ?><a class="direct-history-row" href="devoluciones.php?id=<?= (int)$row['id'] ?>"><span><?= $e($row['invoice_name'].' · '.$row['seller_name']) ?><small><?= $e($row['created_at']) ?></small></span><strong><?= $e(['pending'=>'Pendiente','done'=>'Recibida','rejected'=>'Rechazada'][$row['status']]) ?></strong></a><?php endforeach; ?><?php if(!$page['rows']): ?><p>No hay devoluciones. Puedes solicitarlas desde el detalle de una venta.</p><?php endif; ?></section>
<?php else: ?>
<?php if(!$detail): ?><form method="get" class="direct-supply-picker"><label>Vendedor<select name="seller_id" required><?php foreach($page['sellers'] as $seller): ?><option value="<?= (int)$seller['id'] ?>" <?= (int)$seller['id']===$page['seller_id']?'selected':'' ?>><?= $e($seller['name']) ?></option><?php endforeach; ?></select></label><label>Jornada<input type="date" name="closing_date" value="<?= $e($page['closing_date']) ?>" max="<?= commerceToday() ?>" required></label><button class="contact-button" type="submit">Consultar jornada</button></form><?php endif; ?>
<?php if($detail): ?><p class="notice">Cierre de <?= $e($detail['seller_name'].' · '.$detail['closing_date']) ?> · <?= $detail['status']==='validated'?'Validado':'En revisión' ?>. La información conserva lo capturado al enviarlo.</p><?php endif; ?>
<?php if($page['summary']): require __DIR__.'/day-summary.php'; ?>
<section class="contact-sheet direct-supply"><h2>Efectivo declarado y revisión</h2><p>El cierre registra una declaración del efectivo de estos cobros. No confirma pagos ni genera movimientos de caja. Las ventas y cobros posteriores se consultan en la jornada actual y no reescriben un cierre enviado.</p>
<?php if(!$detail&&permissionHas('venta_directa.closing','create')): ?><form method="post" class="direct-simple-form"><input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><input type="hidden" name="action" value="direct_close"><input type="hidden" name="seller_id" value="<?= $page['seller_id'] ?>"><input type="hidden" name="closing_date" value="<?= $e($page['closing_date']) ?>">
<?php foreach($page['summary']['money'] as $currency=>$totals): ?><label>Efectivo contado / entregado declarado en <?= $e($currency) ?><input name="declared[<?= $e($currency) ?>]" inputmode="decimal" value="<?= $e($page['input']['declared'][$currency]??'0.00') ?>" required><small>Efectivo registrado: <?= $e($totals['cash']) ?>. La diferencia quedará en el cierre.</small></label><?php endforeach; ?><label>Observación<textarea name="notes" maxlength="1000"><?= $e($page['input']['notes']??'') ?></textarea></label><button class="contact-button contact-button-primary">Enviar cierre para revisión</button></form>
<?php elseif($detail): ?><?php foreach($page['declared'] as $currency=>$totals): ?><p><?= $e($currency) ?> · Declarado: <strong><?= $e($totals['cash']) ?></strong> · Esperado: <?= $e($totals['expected']) ?> · Diferencia: <?= $e($totals['difference']) ?></p><?php endforeach; ?><p><?= $e($detail['notes']) ?></p>
<?php if($detail['status']==='submitted'&&permissionScope('venta_directa.closing','confirm')==='all'): ?><form method="post"><input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><button name="action" value="direct_close_validate" class="contact-button contact-button-primary">Validar cierre revisado</button></form><?php endif; ?><?php endif; ?></section><?php endif; ?>
<section class="contact-sheet direct-supply"><h2>Cierres enviados</h2><?php foreach($page['rows'] as $row): ?><a class="direct-history-row" href="cierre.php?id=<?= (int)$row['id'] ?>"><span><?= $e($row['seller_name'].' · '.$row['closing_date']) ?></span><strong><?= $row['status']==='validated'?'Validado':'En revisión' ?></strong></a><?php endforeach; ?><?php if(!$page['rows']): ?><p>Aún no hay cierres enviados.</p><?php endif; ?></section>
<?php endif; ?>
</main><nav class="direct-bottom-nav" aria-label="Accesos móviles"><?php foreach($nav as [$href,$label]): ?><a href="<?= $e($href) ?>"><?= $e(match($label){'Inventario para abastecer'=>'Almacenes','Devoluciones'=>'Devolver','Ventas realizadas'=>'Ventas',default=>$label}) ?></a><?php endforeach; ?></nav></div></body></html>
